if(($_GET['download']??'')==='mapping'){$plan=$runId?json_decode(item_code_run($runId)['plan_json'],true):item_code_plan();$heads=['Product ID','Old Item Code','New Item Code','Product Description','Brand','Main Category','Subcategory','Active'];$rows=array_map(fn($l)=>[$l['id'],$l['old'],$l['new'],$l['name'],$l['brand'],$l['main'],$l['sub'],$l['active']],$plan['lines']);$meta=['Generated'=>date('Y-m-d H:i:s'),'Generated By'=>current_user()['name'],'Status'=>$runId?item_code_run($runId)['status']:'Proposed only; not applied','Rule'=>'Separate numbering per subcategory. Existing valid codes and reserved old-code identities preserved.'];if(($_GET['format']??'')==='print'){report_print_document('Old to New Item Code Mapping',$heads,$rows,$meta);exit;}$path=tempnam(sys_get_temp_dir(),'sku-map-');try{report_write_xlsx($path,'Old to New Item Code Mapping',$heads,$rows,$meta);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="Item_Code_Mapping_'.date('Ymd_His').'.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}exit;}
header('Location: index.php?page=fresh_start');exit;
}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();inventory_write_unlock($lock);if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(400);echo e(safe_error_message($e));exit;}flash(safe_error_message($e),'danger');header('Location: index.php?page=fresh_start'.($runId?'&run='.$runId:''));exit;}
